const body = $input.first().json.body;
const entry = body.entry?.[0]?.changes?.[0]?.value;
const msg = entry?.messages?.[0];
const contato = entry?.contacts?.[0];

const wa_id = msg?.from;
const nome = contato?.profile?.name || null;
const tipo_mensagem = msg?.type || 'unknown';
const audio_media_id = msg?.audio?.id || null;
const texto = msg?.text?.body || '';

let origem = 'tiktok';
if (/\[ref:lp\]/i.test(texto)) origem = 'lp';
else if (/\[ref:tiktok\]/i.test(texto)) origem = 'tiktok';

return [{ json: { wa_id, nome, texto_recebido: texto, tipo_mensagem, audio_media_id, origem } }];

const promptRows = $node["Buscar prompt ativo"].json;
const objetivo = promptRows.find(r => r.chave === 'objetivo')?.conteudo || '';
const compliance = promptRows.find(r => r.chave === 'compliance')?.conteudo || '';
const objecoes = promptRows.find(r => r.chave === 'objecoes')?.conteudo || '';
const historico = ($node["Buscar historico"].json || []).reverse();
const extra = $node["Extrair mensagem e origem"].json;
const textoFinal = $node["Merge apos audio/texto"].json.texto_recebido;
const produtos = $node["Buscar produtos"].json || [];
// O upsert devolve a linha ja mesclada (return=representation) -- entao email/cpf
// gravados numa conversa anterior chegam aqui de graca, sem query extra.
const leadSalvo = ($node["Upsert lead"].json || [])[0] || {};

const catalogoTexto = produtos.map(p => {
  let linha = '- ' + p.produto_id + ' (' + p.tipo + '): ' + p.nome + ' - R$ ' + (p.preco_centavos/100).toFixed(2);
  if (p.resolve_objecao && p.resolve_objecao.length) linha += ' [resolve objecao: ' + p.resolve_objecao.join(', ') + ']';
  if (p.arquetipos && p.arquetipos.length) linha += ' [arquetipo: ' + p.arquetipos.join(', ') + ']';
  return linha;
}).join('\n');

// Tabela de desconto REAL, calculada com a MESMA formula usada em "Montar items do carrinho".
// O modelo nunca deve inventar ou recalcular estes numeros -- precisam bater exatamente
// com o valor que sera de fato cobrado no BlackCat.
function calcularTotal(itens) {
  const fator = 1 - (Math.max(0, itens.length - 1) * 10) / 100;
  return itens.reduce((soma, p) => soma + Math.round(p.preco_centavos * fator), 0);
}
function fmt(centavos) {
  return (centavos / 100).toFixed(2).replace('.', ',');
}

const principal = produtos.find(p => p.tipo === 'principal');
const bumps = produtos.filter(p => p.tipo === 'order_bump').sort((a, b) => a.ordem - b.ordem);

let tabelaDesconto = '';
if (principal && bumps.length) {
  let acumulado = [principal];
  const linhas = [];
  for (const bump of bumps) {
    const semDesconto = acumulado.reduce((s, p) => s + p.preco_centavos, 0) + bump.preco_centavos;
    acumulado = [...acumulado, bump];
    const comDesconto = calcularTotal(acumulado);
    const descontoPct = Math.max(0, acumulado.length - 1) * 10;
    const economia = semDesconto - comDesconto;
    linhas.push('*+ ' + bump.nome + '* (R$ ' + fmt(bump.preco_centavos) + ')\n   Total: R$ ' + fmt(comDesconto) + ' - voce economiza *R$ ' + fmt(economia) + '* (' + descontoPct + '% OFF)');
  }
  tabelaDesconto = '*Sua ' + principal.nome + ' - R$ ' + fmt(principal.preco_centavos) + '*\n\nVeja como o valor final cai conforme voce completa sua protecao:\n\n' + linhas.join('\n\n') + '\n\nEscolha quantos quiser -- quanto mais completa, maior o desconto';
}

const systemPrompt = objetivo + '\n\n' + compliance
  + (objecoes ? '\n\nGUIA DE OBJECOES (referencia para responder recusas e duvidas, sempre dentro do compliance acima):\n' + objecoes : '')
  + '\n\nOrigem do lead nesta conversa: ' + extra.origem + '.'
  + '\n\nCatalogo de produtos disponiveis (use exatamente estes produto_id em produtos_aceitos, nunca invente produto ou preco fora desta lista):\n' + catalogoTexto
  + '\n\nQuando o lead aceitar o produto principal, apresente TODOS os order_bump de uma vez (nao um a um). Use EXATAMENTE este texto para mostrar a economia (os numeros ja estao calculados e batem com o valor real cobrado -- nunca invente ou recalcule):\n\n' + tabelaDesconto
  + '\n\nVoce pode ajustar saudacao/tom ao redor deste texto, mas NUNCA altere os valores em R$ ou os percentuais.'
  + '\n\nPIVO POR OBJECAO: se o lead recusar o principal ou repetir uma objecao forte (ex: "esta caro", "nao tenho interesse", "vou pensar") DEPOIS de voce ja ter tentado tratar a objecao uma vez, ofereca o produto do catalogo cuja tag [resolve objecao] bate com o sinal. Nao insista mais de uma vez na mesma linha de recusa.'
  + '\n\nARQUETIPO: identifique ao longo da conversa qual arquetipo da lead mais se encaixa (mae_protetora: fala de filhos/familia/protecao; guerreira_fe: fala de batalha/forca/nao desistir; devota_busca: fala de milagre/graca/resposta/sinal; mulher_pertence: fala de comunidade/nao estar sozinha). Quando apresentar o stack, priorize o produto cujo [arquetipo] bate com o perfil identificado. Se nao houver sinal claro ainda na conversa, retorne arquetipo como null -- nunca invente um arquetipo sem evidencia real.\n\nDESCONTO DE RECUPERACAO (pivo por objecao): quando oferecer o produto alternativo da secao de pivo (aquele cuja tag [resolve objecao] bate com o sinal do lead), voce pode mencionar que consegue liberar 20% de desconto para ela fechar agora, nesse momento da conversa. Diga algo como "consigo liberar 20% pra voce fechar agora" -- NUNCA diga que essa condicao e "so hoje", "exclusiva desta semana", "ultima chance" ou qualquer coisa datada/limitada no tempo. E uma concessao real e sempre disponivel para quem chega a esse ponto da conversa, nunca uma urgencia fabricada. Quando gerar o link de pagamento para esse cenario (produto alternativo com o desconto de recuperacao), defina pivo_downsell=true na resposta. Em qualquer outro caso de gerar_link, pivo_downsell=false.'
  + '\n\nDADOS DE PAGAMENTO (email e CPF): a API do BlackCat exige e-mail e CPF do comprador no proprio pedido de criacao da venda -- o link so e gerado se os dois ja estiverem preenchidos, nao da pra completar depois na pagina de checkout. Por isso, assim que o lead aceitar o stack (intent=aceitou_stack) e antes de gerar o link, peca e-mail e CPF numa unica mensagem objetiva (ex.: \"Perfeito! Pra gerar seu link de pagamento, me confirma seu e-mail e CPF?\"). So retorne intent=\"gerar_link\" quando voce ja tiver tanto o e-mail quanto o CPF do lead em algum ponto da conversa (mensagem atual ou historico) -- enquanto faltar qualquer um dos dois, continue com intent=\"aceitou_stack\" pedindo soh o que falta, sem repetir produtos ja aceitos. Extraia e retorne SEMPRE os campos \"email\" e \"cpf\" com o valor mais recente que o lead informou na conversa (atual ou historico), ou null se ainda nao informado. Nunca invente ou deduza email/CPF -- so preencha se o lead escreveu explicitamente.\n\nDADOS JA CONHECIDOS DESTE LEAD (de compras ou conversas anteriores): email=' + (leadSalvo.email || 'nao informado') + ', cpf=' + (leadSalvo.cpf || 'nao informado') + '. Se algum deles ja constar acima, trate como JA INFORMADO: nao peca de novo, reutilize o valor e devolva-o no campo correspondente da resposta. Peca apenas o que estiver como "nao informado".\n\nSINAL DE SOFRIMENTO REAL (objecoes.md, secao P): se a lead demonstrar angustia genuina -- perda, doenca grave, desesperanca, qualquer mencao a se ferir -- isso sobrepoe qualquer objetivo de venda. Pare de vender na hora, acolha com humanidade, nao ofereca produto algum nesta resposta, e retorne intent=\"sofrimento\". Se houver risco a vida, oriente procurar ajuda imediata (CVV 188) na propria resposta. Uma vez que intent=\"sofrimento\" for retornado, um humano sera notificado automaticamente -- voce nao precisa e nao deve tentar resolver isso sozinho nem retomar a venda nesta conversa ate que uma pessoa real intervenha.\n\nResponda SEMPRE em JSON no formato: {"resposta": string, "intent": "qualificando"|"objecao"|"aceitou_stack"|"gerar_link"|"recusou"|"sofrimento", "produtos_aceitos": string[], "arquetipo": "mae_protetora"|"guerreira_fe"|"devota_busca"|"mulher_pertence"|null, "pivo_downsell": boolean, "email": string|null, "cpf": string|null}';

const messages = [{ role: 'system', content: systemPrompt }];
for (const h of historico) {
  if (h.mensagem_lead) messages.push({ role: 'user', content: h.mensagem_lead });
  if (h.mensagem_agente) messages.push({ role: 'assistant', content: h.mensagem_agente });
}
messages.push({ role: 'user', content: textoFinal });

return [{ json: { model: 'gpt-4.1', response_format: { type: 'json_object' }, messages } }];

const content = $input.first().json.choices[0].message.content;
const parsed = JSON.parse(content);
return [{ json: parsed }];

const idsAceitos = $node["Extrair resposta e intent"].json.produtos_aceitos || [];
const pivoDownsell = $node["Extrair resposta e intent"].json.pivo_downsell === true;
const catalogo = $node["Buscar produtos"].json || [];

const selecionados = idsAceitos.map(id => catalogo.find(p => p.produto_id === id)).filter(Boolean);

let descontoPct;
if (pivoDownsell) {
  // Desconto FIXO de recuperacao para o pivo por objecao (catalogo-produtos.md, secao 3).
  // E uma concessao real, sempre disponivel -- nunca rotulada como "so hoje" ou datada
  // (compliance-e-etica.md, secao 2). Constante intencional, nao depende do tamanho do carrinho.
  descontoPct = 20;
} else {
  // Desconto por tamanho do stack (principal + order bumps), 10% por item adicional.
  descontoPct = Math.max(0, selecionados.length - 1) * 10;
}
const fator = 1 - (descontoPct / 100);

const items = selecionados.map(p => ({
  title: p.nome,
  quantity: 1,
  unitPrice: Math.round(p.preco_centavos * fator)
}));
const amount = items.reduce((soma, item) => soma + item.unitPrice * item.quantity, 0);

return [{ json: { items, amount, descontoPct } }];

const base = $node["Extrair mensagem e origem"].json;
let transcricao = "";
try { transcricao = ($input.first().json.text || "").trim(); } catch (e) { transcricao = ""; }
// Transcricao vazia = audio nao compreendido. Nao inventa fala: devolve vazio e deixa
// o IF "Tem texto para responder?" acionar a resposta honesta da secao O do objecoes.md.
return [{ json: { ...base, texto_recebido: transcricao } }];

const item = $input.first();
if (!item.binary || !item.binary.data) {
  // Download falhou (o node anterior segue em erro de proposito): devolve sem binario
  // para o Whisper falhar rapido e o fluxo cair no caminho de 'nao consegui ler'.
  return [{ json: {} }];
}
item.binary.data.fileName = 'audio.ogg';
item.binary.data.mimeType = item.binary.data.mimeType || 'audio/ogg';
return [item];

const q = $input.first().json.query || {};
const esperado = '<<WHATSAPP_VERIFY_TOKEN>>';

if (q['hub.mode'] !== 'subscribe' || q['hub.verify_token'] !== esperado) {
  throw new Error('Handshake recusado: hub.verify_token nao confere com o cadastrado.');
}

// A Meta exige o challenge devolvido cru, sem aspas nem JSON em volta.
return [{ json: { challenge: q['hub.challenge'] } }];

const catalogo = ($node["Buscar produtos (upsell)"].json || []);
const lead = ($node["Buscar lead atualizado"].json || [])[0] || {};

// Nunca oferecer nada a quem pediu para parar (LGPD/compliance secao 5) nem a quem
// foi escalado por sofrimento real -- vender nesse momento seria exatamente o que
// objecoes.md secao P proibe.
const bloqueado = lead.status === "opt_out" || lead.status === "aguardando_humano";
if (bloqueado) return [{ json: { tem_upsell: false, produto: null, motivo: lead.status } }];

const comprados = lead.produtos_comprados || [];
// O item gravado vem do BlackCat, que carrega "title" (o nome), nao produto_id --
// por isso a comparacao aceita as duas formas.
const idsComprados = new Set(comprados.map(i => i.produto_id || i.title));

const candidatos = catalogo
  .filter(p => p.tipo !== "principal")
  .filter(p => !idsComprados.has(p.produto_id) && !idsComprados.has(p.nome))
  .sort((a, b) => a.ordem - b.ordem);

const proximo = candidatos[0] || null;
if (!proximo) return [{ json: { tem_upsell: false, produto: null, mensagem: null, motivo: "ja_tem_tudo" } }];

// Preco formatado a partir do catalogo, nunca hardcoded.
const preco = (proximo.preco_centavos / 100).toFixed(2).replace(".", ",");
const mensagem = "Aproveitando que voce ja garantiu a sua protecao: quer completar com *"
  + proximo.nome + "* por apenas R$ " + preco
  + "? Se quiser, me diz \"sim\" que eu ja te mando o link.";

return [{ json: { tem_upsell: true, produto: proximo, mensagem, motivo: null } }];

const itens = $input.first().json;
const base = 'https://salles-ai-agent.pikapod.net' + '/webhook/fila-decidir';
let texto = 'Sugestoes do Hermes pendentes (' + itens.length + '):\n\n';
for (const s of itens) {
  texto += '[' + s.risco_conformidade.toUpperCase() + '] ' + s.area + '\n';
  texto += s.problema_observado + '\n';
  texto += 'Aprovar: ' + base + '?id=' + s.sugestao_id + '&decisao=aprovada\n';
  texto += 'Rejeitar: ' + base + '?id=' + s.sugestao_id + '&decisao=rejeitada\n\n';
}
return [{ json: { texto } }];

const s = $input.first().json[0];
let chave = 'skill:' + (s.arquivo_alvo || 'desconhecido');
if (/objetivo\.md$/.test(s.arquivo_alvo)) chave = 'objetivo';
else if (/compliance-e-etica\.md$/.test(s.arquivo_alvo)) chave = 'compliance';
return [{ json: { chave, conteudo: s.mudanca_proposta, sugestao_id: s.sugestao_id } }];
